PUBLIC aesRoundAsm
ALIGN 16
aesRoundAsm PROC
    db 0F3h, 00Fh, 01Eh, 0FAh ; endbr64
    mov rax, rcx
    mov r10, rdx
    movdqu xmm0, XMMWORD PTR [rax]
    movdqu xmm1, XMMWORD PTR [r10]
    aesenc xmm0, xmm1
    movdqu XMMWORD PTR [rax], xmm0
    pxor xmm0, xmm0
    pxor xmm1, xmm1
    xor rax, rax
    xor r10, r10
    ret
aesRoundAsm ENDP

PUBLIC aesRoundVexAsm
